local ParkourGameUtil = import("Game.Activity.ParkourGame.ParkourGameUtil")

---@class TrackItem
local TrackItem = Class("TrackItem")

function TrackItem:SetPool(pool,poolRoot)
    ---@type Pool
    self.pool = pool
    self.poolRoot = poolRoot
end

function TrackItem:Awake()
    self.gameObject = self.controller.gameObject
    self.transform = self.controller.transform
    self.recycled = false
end
