function TrackItem:Recycle()
    CfUtils.SetActive(self.controller.gameObject,false)
    self.recycled = true
    self.controller.transform:SetParent(self.poolRoot)
    self.pool:Free(self)
end

function TrackItem:Type()
    return ParkourGameUtil.TrackItemType.Default
end
return TrackItem